INSERT OR IGNORE INTO prompt_presets (id, name, category, description, body_json, created_at, updated_at)
VALUES ('p_builtin_poster_split', '城市风景 · 上下分区艺术海报', '艺术海报', '把真实城市/风景照片转成上下分区的极简杂志风海报：上半保留原照质感，下半提炼为 gouache 插画，底部排英文主副标题。需要自备 1 张照片作参考图，文字部分若不够清晰可后期自行排版。', '{"prompt":"Turn the real city or landscape photograph given as @1 into a refined vertical art poster divided into two horizontal bands.\n\nUPPER BAND — keep the original photograph almost intact. Preserve the composition, skyline, architecture, lighting, clouds, moon and every main subject exactly as in the source image. Apply only a gentle cinematic grade: slightly reduced saturation, soft contrast, and a quiet muted palette of blue-grey, warm yellow and off-white. No HDR, no heavy sharpening, no AI-repainting feel, no plastic smoothness.\n\nLOWER BAND — distill the most recognisable elements of the photograph above into a minimal editorial illustration. Do not trace pixel by pixel, abstract and simplify instead:\n- buildings reduced to flat geometric colour blocks\n- the distant skyline compressed into small rectangular silhouettes\n- clouds turned into soft horizontal brush strokes\n- sky and ground kept to a few restrained lines\n- the moon simplified into a small crescent\nIllustration texture: soft gouache, dry-brush edges, watercolour-like transparency, subtle paper grain, hand-painted editorial illustration, matte printed feel. No visible outlines, no cartoon look, no cyberpunk, no 3D, no vector-icon feel. Leave generous off-white negative space, keeping the layout sparse, balanced, quiet, poetic and modern.\n\nPalette: warm ivory, muted navy, blue grey, smoky grey, warm ochre, mustard yellow, soft beige, all at low saturation.\n\nTYPOGRAPHY — place minimal magazine-style English type in the lower area:\n- main title: compose an elegant English title from the image content, set in a classic serif, deep blue-grey\n- subtitle: compose a fine editorial italic serif subtitle from the image content\n- left aligned, restrained type size, ample breathing room\n\nThe finished image should read like a page from an independent art magazine, a city travel photography book, a contemporary art book cover, or a museum shop poster. The illustration below must be instantly recognisable as an artistic distillation of the photograph above, but never a mechanical copy. Keep the whole piece premium, restrained, quiet and poetic, with a paper-print texture. Avoid commercial advertising feel, cheap AI-generated look and busy ornament.\n\nVertical poster, 2:3 ratio, high resolution, premium editorial composition.","refs":[],"aspect":"2:3","tier":"2K","includeRefNotes":true}', '2026-10-18T00:00:00Z', '2026-10-18T00:00:00Z');
